118	// encodeFile 把内存状态编码为完整文件字节。
119	func encodeFile(st *mapState) ([]byte, error) {
120		fd := fileData{
121			Version:       int(fileVersion),
122			Config:        st.config,
123			Trajectory:    st.trajectory,
124			Landmarks:     make([]landmarkJSON, 0, len(st.landmarks)),
125			Segments:      make([]segmentJSON, 0, len(st.segments)),
126			Sources:       make([]*frameSrcJSON, len(st.sources)),
127			Corrections:   make([]corrRecJSON, 0, len(st.corrections)),
128			Invalidations: make([]invalJSON, 0, len(st.invalRecords)),
129		}
130		for id, lm := range st.landmarks {
131			lj := landmarkJSON{ID: id, Occurrences: make([]occurrenceJSON, 0, len(lm.appearances))}
132			for i, occ := range lm.appearances {
133				oj := occurrenceJSON{
134					Number:        i + 1,
135					X:             occ.x,
136					Y:             occ.y,
137					Count:         occ.count,
138					LegacyCount:   occ.legacyCount,
139					LegacyMX:      occ.legacyMX,
140					LegacyMY:      occ.legacyMY,
141					FirstSeenTime: occ.firstSeenTime,
142					HasFirstSeen:  occ.hasFirstSeen,
143					Active:        occ.active,
144				}
145				if !occ.active {
146					oj.InvalidTime = occ.invalidTime
147					oj.InvalidReason = occ.invalidReason
148					oj.InvalidOpID = occ.invalidOpID
149				}
150				lj.Occurrences = append(lj.Occurrences, oj)
151			}
152			fd.Landmarks = append(fd.Landmarks, lj)
153		}
154		for id, rec := range st.segments {
155			fd.Segments = append(fd.Segments, segmentJSON{ID: id, Hash: rec.hash, Result: rec.result})
156		}
157		for k, src := range st.sources {
158			if src == nil {
159				continue // 旧文件帧在新文件中保留为 null，表示仍无逐帧依据
160			}
161			obs := append([]Observation(nil), src.observations...)
162			fd.Sources[k] = &frameSrcJSON{MoveVariance: src.moveVariance, Observations: obs}
163		}
164		for _, rec := range st.corrections {
165			cj := corrRecJSON{
166				ID:        rec.ID,
167				Anchor:    rec.Anchor,
168				Target:    rec.Target,
169				EndTime:   rec.EndTime,
170				Poses:     make([]poseChangeJSON, len(rec.Poses)),
171				Landmarks: make([]landmarkChangeJSON, len(rec.Landmarks)),
172			}
173			for i, pc := range rec.Poses {
174				cj.Poses[i] = poseChangeJSON{Before: pc.Before, After: pc.After}
175			}
176			for i, lc := range rec.Landmarks {
177				cj.Landmarks[i] = landmarkChangeJSON{ID: lc.ID, Occurrence: lc.Occurrence, Before: lc.Before, After: lc.After}
178			}
179			fd.Corrections = append(fd.Corrections, cj)
180		}
181		for _, rec := range st.invalRecords {
182			ij := invalJSON{
183				ID:        rec.id,
184				Reason:    rec.reason,
185				Hash:      rec.hash,
186				Time:      rec.result.Time,
187				Landmarks: make([]invalLMJSON, len(rec.result.Landmarks)),
188			}
189			for i, l := range rec.result.Landmarks {
190				ij.Landmarks[i] = invalLMJSON{ID: l.ID, Occurrence: l.Occurrence}
191			}
192			fd.Invalidations = append(fd.Invalidations, ij)
193		}
194		payload, err := json.Marshal(&fd)
195		if err != nil {
196			return nil, fmt.Errorf("posemap: encode state: %w", err)
197		}
198	
199		out := make([]byte, headerLen+len(payload)+4)
200		copy(out[0:8], fileMagic)
201		binary.BigEndian.PutUint16(out[8:10], fileVersion)
202		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
203		copy(out[headerLen:], payload)
204		sum := crc32.ChecksumIEEE(out[:headerLen+len(payload)])
205		binary.BigEndian.PutUint32(out[headerLen+len(payload):], sum)
206		return out, nil
207	}
208	
209	// loadFile 只读取证地解析地图文件。
210	func loadFile(path string) (*mapState, error) {
211		raw, err := os.ReadFile(path)
212		if err != nil {
213			return nil, err // 含 fs.ErrNotExist，交由调用方/上层用 errors.Is 判断
214		}
215		if len(raw) < headerLen+4 || string(raw[:8]) != fileMagic {
216			return nil, fmt.Errorf("%w: unrecognized header", ErrCorrupt)
217		}
218		version := binary.BigEndian.Uint16(raw[8:10])
219		if version != fileVersion {
220			return nil, fmt.Errorf("%w: version %d", ErrUnsupportedVersion, version)
221		}
222		length := binary.BigEndian.Uint32(raw[10:14])
223		if int(length) != len(raw)-headerLen-4 {
224			return nil, fmt.Errorf("%w: truncated or length mismatch", ErrCorrupt)
225		}
226		want := binary.BigEndian.Uint32(raw[len(raw)-4:])
227		if crc32.ChecksumIEEE(raw[:len(raw)-4]) != want {
228			return nil, fmt.Errorf("%w: checksum mismatch", ErrCorrupt)
229		}
230	
231		var fd fileData
232		if err := json.Unmarshal(raw[headerLen:headerLen+int(length)], &fd); err != nil {
233			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
234		}
235		if err := validateLoaded(&fd); err != nil {
236			return nil, err
237		}
238	
239		st := &mapState{
240			config:       fd.Config,
241			trajectory:   fd.Trajectory,
242			landmarks:    make(map[string]*landmarkState, len(fd.Landmarks)),
243			segments:     make(map[string]*segmentRecord, len(fd.Segments)),
244			sources:      make([]*frameSource, len(fd.Trajectory)-1),
245			corrections:  make([]*CorrectionRecord, 0, len(fd.Corrections)),
246			corrIndex:    make(map[string]string, len(fd.Corrections)),
247			invalRecords: make([]*invalidationRecord, 0, len(fd.Invalidations)),
248			invalIndex:   make(map[string]*invalidationRecord, len(fd.Invalidations)),
249		}
250		// 旧文件不携带逐帧依据：有帧而 sources 缺省即旧地图。无帧时二者
251		// 无法区分也无需区分（尚无范围可校正）。
252		oldFormat := len(fd.Sources) == 0 && len(fd.Trajectory) > 1
253		for _, lmj := range fd.Landmarks {
254			lm := &landmarkState{}
255			if len(lmj.Occurrences) > 0 {
256				// 新格式：历次出现按编号递增保存。
257				for _, oj := range lmj.Occurrences {
258					lm.appearances = append(lm.appearances, &occurrenceState{
259						x:             oj.X,
260						y:             oj.Y,
261						count:         oj.Count,
262						legacyCount:   oj.LegacyCount,
263						legacyMX:      oj.LegacyMX,
264						legacyMY:      oj.LegacyMY,
265						firstSeenTime: oj.FirstSeenTime,
266						hasFirstSeen:  oj.HasFirstSeen,
267						active:        oj.Active,
268						invalidTime:   oj.InvalidTime,
269						invalidReason: oj.InvalidReason,
270						invalidOpID:   oj.InvalidOpID,
271					})
272				}
273			} else {
274				// 兼容旧布局：一个平铺路标即第 1 次有效出现。
275				occ := &occurrenceState{
276					x:      lmj.X,
277					y:      lmj.Y,
278					count:  lmj.Count,
279					active: true,
280				}
281				if oldFormat {
282					// 旧文件中该路标的全部既有观测都是固定旧贡献，位置取
283					// 文件中的聚合值；缺少逐帧来源，首次观测时间未知。
284					occ.legacyCount = lmj.Count
285					occ.legacyMX, occ.legacyMY = lmj.X, lmj.Y
286					occ.hasFirstSeen = false
287				} else {
288					occ.legacyCount = lmj.LegacyCount
289					occ.legacyMX, occ.legacyMY = lmj.LegacyMX, lmj.LegacyMY
290					// 含固定旧贡献时最早观测缺少来源，首次观测时间未知；
291					// 否则从逐帧依据中恢复该出现第一次被观测到的帧时间。
292					occ.hasFirstSeen = lmj.LegacyCount == 0
293					if occ.hasFirstSeen {
294						for k, src := range fd.Sources {
295							if src == nil {
296								continue
297							}
298							found := false
299							for _, ob := range src.Observations {
300								if ob.ID == lmj.ID {
301									found = true
302									break
303								}
304							}
305							if found {
306								occ.firstSeenTime = fd.Trajectory[k+1].Time
307								break
308							}
309						}
310					}
311				}
312				lm.appearances = append(lm.appearances, occ)
313			}
314			st.landmarks[lmj.ID] = lm
315		}
316		for _, sg := range fd.Segments {
317			ids := sg.Result.LandmarkIDs
318			if ids == nil {
319				ids = []string{}
320			}
321			st.segments[sg.ID] = &segmentRecord{
322				hash:   sg.Hash,
323				result: ImportResult{EndPose: sg.Result.EndPose, LandmarkIDs: ids},
324			}
325		}
326		if !oldFormat {
327			for k, src := range fd.Sources {
328				if src == nil {
329					continue // 来自旧文件的帧：保持依据缺失
330				}
331				obs := append([]Observation(nil), src.Observations...)
332				st.sources[k] = &frameSource{moveVariance: src.MoveVariance, observations: obs}
333			}
334		}
335		for _, cj := range fd.Corrections {
336			rec := &CorrectionRecord{
337				ID:        cj.ID,
338				Anchor:    cj.Anchor,
339				Target:    cj.Target,
340				EndTime:   cj.EndTime,
341				Poses:     make([]PoseChange, len(cj.Poses)),
342				Landmarks: make([]LandmarkChange, len(cj.Landmarks)),
343			}
344			for i, pc := range cj.Poses {
345				rec.Poses[i] = PoseChange{Before: pc.Before, After: pc.After}
346			}
347			for i, lc := range cj.Landmarks {
348				occNum := lc.Occurrence
349				if occNum == 0 {
350					occNum = 1 // 更早版本写出的校正记录不带编号，只有第 1 次出现
351				}
352				rec.Landmarks[i] = LandmarkChange{ID: lc.ID, Occurrence: occNum, Before: lc.Before, After: lc.After}
353			}
354			st.corrections = append(st.corrections, rec)
355			st.corrIndex[cj.ID] = canonicalCorrectionHash(cj.Anchor, cj.Target)
356		}
357		for _, ij := range fd.Invalidations {
358			lms := make([]InvalidatedLandmark, len(ij.Landmarks))
359			for i, l := range ij.Landmarks {
360				lms[i] = InvalidatedLandmark{ID: l.ID, Occurrence: l.Occurrence}
361			}
362			rec := &invalidationRecord{
363				id:     ij.ID,
364				reason: ij.Reason,
365				hash:   ij.Hash,
366				result: InvalidationResult{Time: ij.Time, Landmarks: lms},
367			}
368			st.invalRecords = append(st.invalRecords, rec)
369			st.invalIndex[ij.ID] = rec
370		}
371		return st, nil
372	}
373	
374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		timeAt := func(t int64) bool {
409			for _, p := range fd.Trajectory {
410				if p.Time == t {
411					return true
412				}
413			}
414			return false
415		}
416		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
417		for _, lm := range fd.Landmarks {
418			if lm.ID == "" {
419				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
420			}
421			if _, dup := seenIDs[lm.ID]; dup {
422				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
423			}
424			seenIDs[lm.ID] = struct{}{}
425			if len(lm.Occurrences) == 0 {
426				// 兼容旧布局：平铺字段表示第 1 次出现。
427				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
428					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
429				}
430				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
431					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
432				}
433				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
434					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
435				}
436				continue
437			}
438			activeCount := 0
439			for i, oj := range lm.Occurrences {
440				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
441					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
442				}
443				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
444					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
445				}
446				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
447					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
448				}
449				if oj.Active {
450					activeCount++
451					if i != len(lm.Occurrences)-1 {
452						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
453					}
454				} else if oj.InvalidReason == "" {
455					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
456				}
457				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
458				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
459				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
460				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
461				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
462				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
463				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
464				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
465				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
466				// 观测无关。
467				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
468					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
469				}
470				if i > 0 {
471					if !oj.HasFirstSeen {
472						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
473					}
474					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
475					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
476						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
477					}
478				}
479			}
480			if activeCount > 1 {
481				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
482			}
483		}
484		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
485		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
486		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
487		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
488		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
489		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
490		if len(fd.Sources) != 0 {
491			bounds := make(map[string][]occurrenceWindow, len(fd.Landmarks))
492			for _, lm := range fd.Landmarks {
493				bounds[lm.ID] = occurrenceWindowsOf(lm)
494			}
495			for k, src := range fd.Sources {
496				if src == nil {
497					continue // 旧地图帧：无逐帧依据，不要求补齐归属
498				}
499				t := fd.Trajectory[k+1].Time
500				for _, ob := range src.Observations {
501					wins, ok := bounds[ob.ID]
502					if !ok {
503						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
504					}
505					if occurrenceNumberAt(wins, t) == 0 {
506						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
507					}
508				}
509			}
510		}
511		segIDs := make(map[string]struct{}, len(fd.Segments))
512		for _, sg := range fd.Segments {
513			if sg.ID == "" || sg.Hash == "" {
514				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
515			}
516			if _, dup := segIDs[sg.ID]; dup {
517				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
518			}
519			segIDs[sg.ID] = struct{}{}
520		}
521		corrIDs := make(map[string]struct{}, len(fd.Corrections))
522		for _, cr := range fd.Corrections {
523			if cr.ID == "" || !timeAt(cr.Anchor) || !timeAt(cr.EndTime) || cr.Anchor > cr.EndTime {
524				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
525			}
526			if len(cr.Poses) == 0 {
527				return fmt.Errorf("%w: correction %s has no affected poses", ErrCorrupt, cr.ID)
528			}
529			for _, pc := range cr.Poses {
530				if !finitePose(pc.Before) || !finitePose(pc.After) {
531					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
532				}
533			}
534			for _, lc := range cr.Landmarks {
535				if lc.ID == "" {
536					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
537				}
538				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
539					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
540					lc.Before.Count < 1 || lc.After.Count < 1 {
541					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
542				}
543			}
544			if _, dup := corrIDs[cr.ID]; dup {
545				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
546			}
547			corrIDs[cr.ID] = struct{}{}
548		}
549		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
550		for _, iv := range fd.Invalidations {
551			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
552				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
553			}
554			if _, dup := invalIDs[iv.ID]; dup {
555				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
556			}
557			invalIDs[iv.ID] = struct{}{}
558			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
559			for _, l := range iv.Landmarks {
560				if l.ID == "" || l.Occurrence < 1 {
561					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
562				}
563				if _, dup := lmSeen[l.ID]; dup {
564					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
565				}
566				lmSeen[l.ID] = struct{}{}
567			}
568		}
569		return nil
570	}
571	
572	func finitePose(p Pose) bool {
573		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
574	}
575	
576	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
577	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
578	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
579		h := sha256.New()
580		var b [8]byte
581		binary.BigEndian.PutUint64(b[:], uint64(anchor))
582		h.Write(b[:])
583		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
584			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
585			h.Write(b[:])
586		}
587		return fmt.Sprintf("%x", h.Sum(nil))
588	}
589	
590	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
591	func (m *Map) saveExclusive() error {
592		data, err := encodeFile(m.state)
593		if err != nil {
594			return err
595		}
596		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
597		if err != nil {
598			return err
599		}
600		return writeAndClose(f, data, m.path)
601	}
602	
603	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
604	func (m *Map) saveReplace() (err error) {
605		data, err := encodeFile(m.state)
606		if err != nil {
607			return err
608		}
609		dir, base := filepath.Split(m.path)
610		if dir == "" {
611			dir = "."
612		}
613		f, err := os.CreateTemp(dir, base+".tmp-*")
614		if err != nil {
615			return err
616		}
617		tmpName := f.Name()
618		// 任何失败路径都尽力清理临时文件。
619		defer func() {
620			if err != nil {
621				_ = os.Remove(tmpName)
622			}
623		}()
624		if err = writeAndClose(f, data, tmpName); err != nil {
625			return err
626		}
627		if err = os.Rename(tmpName, m.path); err != nil {
628			return err
629		}
630		return nil
631	}
632	
633	func writeAndClose(f *os.File, data []byte, name string) (err error) {
634		defer func() {
635			if cerr := f.Close(); err == nil {
636				err = cerr
637			}
638		}()
639		if _, err = f.Write(data); err != nil {
640			return err
641		}
642		if err = f.Sync(); err != nil {
643			return err
644		}
645		return nil
646	}
647	
648	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
649	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
650	func canonicalHash(frames []Frame) string {
651		h := sha256.New()
652		var lenBuf [4]byte
653		var numBuf [8]byte
654		putU32 := func(v uint32) {
655			binary.BigEndian.PutUint32(lenBuf[:], v)
656			h.Write(lenBuf[:])
657		}
658		putU64 := func(v uint64) {
659			binary.BigEndian.PutUint64(numBuf[:], v)
660			h.Write(numBuf[:])
661		}
662		putStr := func(s string) {
663			putU32(uint32(len(s)))
664			h.Write([]byte(s))
665		}
666	
667		putU32(uint32(len(frames)))
668		for _, fr := range frames {
669			putU64(uint64(fr.Time))
670			putU64(math.Float64bits(fr.DX))
671			putU64(math.Float64bits(fr.DY))
672			putU64(math.Float64bits(fr.DHeading))
673			putU64(math.Float64bits(fr.MoveVariance))
674			putU32(uint32(len(fr.Observations)))
675			for _, ob := range fr.Observations {
676				putStr(ob.ID)
677				putU64(math.Float64bits(ob.X))
678				putU64(math.Float64bits(ob.Y))
679			}
680		}
681		return fmt.Sprintf("%x", h.Sum(nil))
682	}
683

