	}}); err != nil {
		t.Fatal(err)
	}
	c1 := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Variance: 2}}
	r1, err := m.Correct(c1)
	if err != nil {
		t.Fatal(err)
	}
	// 第二次校正以当时最新状态为起点，把末帧 p2 放到 (50,60)。
	c2 := Correction{ID: "c2", Anchor: 200, Target: CorrectionTarget{X: 50, Y: 60, Variance: 7}}
	r2, err := m.Correct(c2)
	if err != nil {
