487		m2, err := Open(path)
488		if err != nil {
489			t.Fatal(err)
490		}
491		cur, err := m2.CurrentPose()
492		if err != nil {
493			t.Fatal(err)
494		}
495		if cur.Time != res.EndPose.Time || cur.X != res.EndPose.X || cur.Heading != res.EndPose.Heading ||
496			cur.Variance != res.EndPose.Variance {
497			t.Fatalf("after reopen current = %+v, want %+v", cur, res.EndPose)
498		}
499		p, err := m2.PoseAt(100)
500		if err != nil || p.Time != 100 {
